#!/usr/bin/env python3
"""Apply V3.1.5 to the integrated beta branch only."""
import json
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FILES = {'.nvmrc': '22\n', '.github/workflows/community-checks.yml': "name: Community Edition Checks\non:\n  push:\n    branches: [main, 'feature/**']\n  pull_request:\npermissions:\n  contents: read\njobs:\n  python:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v6\n        with:\n          persist-credentials: false\n      - uses: actions/setup-python@v6\n        with:\n          python-version: '3.12'\n      - name: Compile Python scripts\n        run: python -m py_compile sync_garmin.py import_garmin_history.py\n      - name: Run tests\n        run: python -m unittest discover -s tests -v\n  dashboard:\n    runs-on: ubuntu-latest\n    defaults:\n      run:\n        working-directory: dashboard\n    steps:\n      - uses: actions/checkout@v6\n        with:\n          persist-credentials: false\n      - uses: actions/setup-node@v6\n        with:\n          node-version-file: .nvmrc\n          cache: npm\n          cache-dependency-path: dashboard/package-lock.json\n      - run: npm ci --no-audit --no-fund\n      - run: npm run build\n", '.github/workflows/garmin-history.yml': "name: Garmin History Import\non:\n  workflow_dispatch:\n    inputs:\n      month:\n        description: 'Mese da importare (YYYY-MM, non futuro)'\n        required: true\n        type: string\npermissions:\n  contents: read\nconcurrency:\n  group: garmin-database-writer\n  cancel-in-progress: false\njobs:\n  import-history:\n    runs-on: ubuntu-latest\n    timeout-minutes: 45\n    steps:\n      - uses: actions/checkout@v6\n        with:\n          persist-credentials: false\n      - uses: actions/setup-python@v6\n        with:\n          python-version: '3.12'\n      - name: Install dependencies\n        run: python -m pip install -r requirements.txt\n      - name: Import Garmin history\n        env:\n          GARMIN_PERSONAL_API_KEY: ${{ secrets.GARMIN_PERSONAL_API_KEY }}\n          SUPABASE_DATABASE_URL: ${{ secrets.SUPABASE_DATABASE_URL }}\n          IMPORT_MONTH: ${{ inputs.month }}\n          GARMIN_TIMEZONE: ${{ vars.GARMIN_TIMEZONE || 'Europe/Rome' }}\n        run: python import_garmin_history.py\n", '.github/workflows/dashboard-pages.yml': 'name: Deploy Garmin Dashboard to GitHub Pages\non:\n  workflow_dispatch:\npermissions:\n  contents: read\n  pages: write\n  id-token: write\nconcurrency:\n  group: pages-dashboard\n  cancel-in-progress: true\njobs:\n  build:\n    # Never deploy this beta to the upstream repository\'s production Pages.\n    if: ${{ github.event.repository.fork && github.ref == \'refs/heads/feature/community-v3-beta\' }}\n    runs-on: ubuntu-latest\n    environment: github-pages\n    steps:\n      - uses: actions/checkout@v6\n        with:\n          persist-credentials: false\n      - uses: actions/setup-node@v6\n        with:\n          node-version-file: .nvmrc\n          cache: npm\n          cache-dependency-path: dashboard/package-lock.json\n      - name: Install dependencies\n        working-directory: dashboard\n        run: npm ci --no-audit --no-fund\n      - name: Build\n        working-directory: dashboard\n        env:\n          VITE_SUPABASE_URL: ${{ vars.VITE_SUPABASE_URL }}\n          VITE_SUPABASE_PUBLISHABLE_KEY: ${{ vars.VITE_SUPABASE_PUBLISHABLE_KEY }}\n          GITHUB_PAGES_BASE: /${{ github.event.repository.name }}/\n        run: |\n          test -n "$VITE_SUPABASE_URL"\n          test -n "$VITE_SUPABASE_PUBLISHABLE_KEY"\n          npm run build\n      - uses: actions/configure-pages@v5\n      - uses: actions/upload-pages-artifact@v3\n        with:\n          path: dashboard/dist\n      - uses: actions/deploy-pages@v4\n', 'README.md': '# Garmin Coaching Hub — Community V3.1.5 Beta\n\nDashboard personale per attività Garmin, recupero e Training Load, con sincronizzazione Python, database Supabase e frontend React/TypeScript.\n\nQuesta beta è destinata a un fork con un account Garmin e un progetto Supabase indipendenti. Non è una piattaforma multi-utente condivisa.\n\n- [Installazione da zero](docs/COMMUNITY_SETUP.md)\n- [Checklist e report di collaudo](docs/BETA_TEST.md)\n- [Training Load](docs/V3_TRAINING_LOAD.md)\n- [Grafici interattivi V3.1.4](README-V3.1.4.md)\n\n## Ambiente di sviluppo\n\nNode.js 22 LTS (minimo 22), npm, Python 3.12, Git.\n\n```sh\ncd dashboard\nnpm ci\nnpm run build\nnpm run dev\n```\n\nPer il frontend locale, copiare `.env.example` in `.env.local` nella cartella dashboard e impostare solo URL pubblico e chiave publishable/anon del proprio progetto. Mai inserire chiavi Garmin, password PostgreSQL o service_role nel frontend.\n\nDalla radice: `python -m unittest discover -s tests -v`.\n\n## Stato della beta\n\nLa V3.1.4 integrata ha superato la build locale e tre test Python; la V3.1.5 richiede una nuova verifica CI e un collaudo con un secondo account. Recharts 2 resta temporaneamente in uso; la migrazione a v3 è separata. Non applicare gli script di patch storici a questa installazione.\n\nLa produzione upstream (`main`) resta separata. Leggere le avvertenze di sicurezza nella guida prima di distribuire il progetto.\n', 'README-BETA.md': '# Community V3.1.5 Beta\n\nIl codice integrato è già presente nel branch `feature/community-v3-beta`. Non serve applicare le vecchie patch V2.1 o V3.1.4.\n\nSeguire [la guida di installazione](docs/COMMUNITY_SETUP.md) e [il piano di collaudo](docs/BETA_TEST.md).\n', 'docs/COMMUNITY_SETUP.md': "# Garmin Coaching Hub — installazione indipendente V3.1.5\n\n## 1. Prerequisiti\n\nAccount GitHub, chiave personale Garmin per la Personal API (non le credenziali Garmin Connect), nuovo progetto Supabase, Git, Node.js 22 LTS e Python 3.12 per le verifiche locali. I workflow cloud installano il proprio ambiente. Verificare disponibilità e limiti dei piani dei servizi.\n\n## 2. Fork\n\nCreare il fork da https://github.com/mschiavo/garmin-coaching-hub scegliendo tutti i branch (disattivare la copia del solo branch predefinito). Se il fork esiste già e manca la beta, clonare il proprio fork ed eseguire:\n\n```sh\ngit remote add upstream https://github.com/mschiavo/garmin-coaching-hub.git\ngit fetch upstream\ngit switch -c feature/community-v3-beta upstream/feature/community-v3-beta\ngit push -u origin feature/community-v3-beta\n```\n\nSe upstream o il branch esistono già, non ricrearli: verificare `git remote -v`, `git branch -a` e sincronizzare senza force push. Nel proprio fork impostare `feature/community-v3-beta` come default branch da Settings. Questo rende disponibili i workflow manuali e fa usare alla pianificazione il codice beta. Non modificare il default branch del repository originale.\n\n## 3. Database e autenticazione\n\nNel SQL Editor di un **nuovo** progetto Supabase eseguire in ordine `supabase/bootstrap.sql` e `supabase/dashboard.sql`. Non eseguire il bootstrap sul database esistente senza una verifica delle migrazioni.\n\nAbilitare l'autenticazione Email, creare un utente email/password, confermare l'email se necessario e disabilitare le registrazioni pubbliche per l'istanza personale. Copiare il suo UUID da Authentication > Users ed eseguire (sostituire il segnaposto):\n\n```sql\nINSERT INTO dashboard_private.allowed_users(user_id)\nVALUES ('UUID-UTENTE') ON CONFLICT (user_id) DO NOTHING;\n```\n\nL'RPC `public.dashboard_data()` consente solo gli utenti nella allowlist. Non rendere pubbliche le tabelle `coaching` per risolvere errori di login.\n\n## 4. Configurazione GitHub\n\nNel fork, Settings > Secrets and variables > Actions:\n\n| Tipo | Nome | Valore |\n|---|---|---|\n| Secret | `GARMIN_PERSONAL_API_KEY` | Chiave personale Garmin |\n| Secret | `SUPABASE_DATABASE_URL` | Connessione PostgreSQL del proprio progetto, con password e SSL; usare un endpoint raggiungibile dal runner (es. session pooler se necessario) |\n| Variable | `VITE_SUPABASE_URL` | URL base `https://<project-ref>.supabase.co` |\n| Variable | `VITE_SUPABASE_PUBLISHABLE_KEY` | Chiave publishable/anon, mai service_role |\n| Variable | `GARMIN_TIMEZONE` | Facoltativa, es. `Europe/Rome` |\n\nI secret non vengono copiati con il fork. Non inserire password, token o URL di connessione nei file o nei report. Usare un URL PostgreSQL con password correttamente codificata.\n\n## 5. Primo avvio\n\nAbilitare Actions nel fork. Eseguire prima `Community Edition Checks`, poi `Test Garmin Authentication`. Eseguire `Garmin Supabase Sync` con 3 giorni. Verificare nel SQL Editor del proprio progetto:\n\n```sql\nSELECT count(*) FROM coaching.garmin_activities;\nSELECT count(*) FROM coaching.garmin_daily_metrics;\n```\n\nUn conteggio zero delle attività può essere legittimo se non ci sono allenamenti nel periodo. Controllare anche le date, la presenza delle metriche e il riepilogo del job: assenza di dati e errori API non sono la stessa cosa.\n\nLa sincronizzazione pianificata usa il branch predefinito e può essere disabilitata finché il collaudo non è completato. La sua frequenza configurata è ogni tre ore. Lo storico usa blocchi da sette giorni e ha un limite di 45 minuti per job. Usare `Garmin History Import` con un mese non futuro in formato `YYYY-MM`, un mese alla volta, nel quale esistono dati. Un job riuscito può comunque avere metriche incomplete: leggere il riepilogo e riprovare se necessario.\n\n## 6. Dashboard locale e pubblicazione\n\nPer la prova locale, nella cartella `dashboard` copiare `.env.example` in `.env.local`, compilare i due valori VITE e lanciare `npm ci`, `npm run build`, `npm run dev`. Accedere con l'utente Supabase autorizzato. Verificare prima che `.env.local` sia ignorato da Git.\n\nPer Pages scegliere Settings > Pages > Source: GitHub Actions. Consentire il branch beta nell'eventuale protezione dell'ambiente `github-pages`. In Actions avviare manualmente `Deploy Garmin Dashboard to GitHub Pages` selezionando `feature/community-v3-beta`. La beta consente il deploy esclusivamente da quel branch in un fork; non deploya sul repository upstream. Aprire il link mostrato dal job. Il percorso previsto è quello standard di un sito progetto GitHub Pages (`/<nome-repository>/`).\n\n## 7. Sicurezza prima della distribuzione\n\nOgni tester usa il proprio progetto, chiave Garmin e account. Non condividere dati personali, screenshot non oscurati o credenziali. L'originale è pubblico: prima di distribuirlo verificare **tutta** la cronologia, incluse versioni precedenti degli ZIP e configurazioni, con secret scanner e revisione manuale. La rimozione di un file dall'ultimo commit non cancella la sua cronologia. Revocare/ruotare eventuali segreti esposti. Questo kit non certifica l'assenza di segreti storici.\n\nCompletare [la checklist](BETA_TEST.md) prima di attivare la sincronizzazione periodica.\n", 'docs/BETA_TEST.md': '# Piano di collaudo — Community V3.1.5 Beta\n\nEseguire esclusivamente con un proprio account Garmin e un nuovo Supabase. Registrare PASS, FAIL o NON TESTATO per ogni voce. Non usare credenziali o dati del maintainer.\n\n## Ambiente e installazione\n\n- [ ] Fork: branch predefinito `feature/community-v3-beta`, SHA annotato.\n- [ ] Node.js 22, `npm ci` senza EBADENGINE; deprecazione Recharts 2 nota.\n- [ ] `npm run build` senza warning chunk; `Community Edition Checks` verde per Python e frontend.\n- [ ] Bootstrap e SQL dashboard su un progetto vuoto.\n- [ ] Login corretto con utente autorizzato; utente non in allowlist non riceve dati; logout funzionante.\n\n## Dati Garmin\n\n- [ ] Test Garmin Authentication riuscito; nessun token nei log.\n- [ ] Sync 3 giorni, date e conteggi coerenti con Garmin.\n- [ ] Ripetizione dello stesso sync senza duplicati (confrontare conteggi per lo stesso intervallo).\n- [ ] Import di un mese passato con dati, preferibilmente antecedente al 2026 se disponibili.\n- [ ] Verifica fuso orario, giornate mancanti e riepilogo delle metriche incomplete.\n- [ ] Verifica che una configurazione errata non dia accesso ai dati di altri account; non usare credenziali altrui.\n\n## Dashboard\n\n- [ ] Avvio locale, deploy Pages nel fork, ricaricamento pagina.\n- [ ] Panoramica, Allenamenti, Recupero, Prestazioni, Insights, Training Load: dati e navigazione.\n- [ ] Assi X/Y con tacche leggibili, griglia, tooltip con valori e unità, legenda.\n- [ ] Volume settimanale e media delle quattro settimane precedenti confrontati con dati sorgente; settimane incomplete identificate; valori assenti non presentati come misurati.\n- [ ] Rapporto di carico e linea 1×; nessun rapporto artificiale quando manca il riferimento.\n- [ ] Selettore Dettaglio settimana, layout desktop/mobile e tocco; nessun errore console.\n- [ ] Stato senza dati, periodi brevi, cambio filtro e nuovo accesso dopo logout.\n\n## Report per il maintainer (senza segreti)\n\n```text\nBranch e SHA:\nNode/npm/Python:\nBrowser e dispositivo:\nBuild e CI:\nBootstrap/login/allowlist:\nSync e ripetizione:\nStorico (mese):\nDashboard e grafici:\nDeploy Pages:\nEsito checklist (PASS/FAIL/NON TESTATO):\nProblema: schermata o job, passaggi per riprodurlo,\nrisultato atteso, risultato effettivo, errore sanitizzato.\n```\n\nNon allegare URL PostgreSQL, chiavi, email, token, metriche personali o schermate non anonimizzate. Non considerare superata una prova non eseguita. La promozione a stabile richiede collaudo indipendente e verifica della sicurezza della cronologia.\n'}

def git(*args):
    return subprocess.check_output(['git', '-C', str(ROOT), *args], text=True).strip()

def main():
    if git('branch', '--show-current') != 'feature/community-v3-beta':
        raise SystemExit('Wrong branch. Switch to feature/community-v3-beta first.')
    if git('status', '--porcelain', '--untracked-files=no'):
        raise SystemExit('Tracked changes exist; commit or stash them before applying.')
    if subprocess.run(['git','-C',str(ROOT),'merge-base','--is-ancestor','e0856ef61f1d6da146db06415a199f90f0e1fdb1','HEAD']).returncode != 0:
        raise SystemExit('Expected integrated beta commit not found in history.')
    package_path = ROOT / 'dashboard/package.json'
    lock_path = ROOT / 'dashboard/package-lock.json'
    package = json.loads(package_path.read_text(encoding='utf-8-sig'))
    lock = json.loads(lock_path.read_text(encoding='utf-8-sig'))
    if package.get('name') != 'garmin-coaching-dashboard' or lock.get('lockfileVersion') != 3:
        raise SystemExit('Unexpected package manifest or lockfile.')
    if lock['packages']['node_modules/@supabase/supabase-js']['version'] != '2.119.2':
        raise SystemExit('Unexpected Supabase version; review before applying.')
    package['engines'] = {'node': '>=22.0.0'}
    lock['packages']['']['engines'] = package['engines']
    updates = dict(FILES)
    updates['dashboard/package.json'] = json.dumps(package, indent=2, ensure_ascii=False) + '\n'
    updates['dashboard/package-lock.json'] = json.dumps(lock, indent=2, ensure_ascii=False) + '\n'
    # Verify tracked target files have not diverged from the integrated baseline.
    for name, content in updates.items():
        target = ROOT / name
        if target.exists() and target.read_text(encoding='utf-8-sig') == content:
            continue
        if target.exists():
            baseline = subprocess.run(['git','-C',str(ROOT),'show','e0856ef61f1d6da146db06415a199f90f0e1fdb1:'+name], capture_output=True)
            if baseline.returncode or baseline.stdout.decode('utf-8-sig').replace('\r\n','\n') != target.read_text(encoding='utf-8-sig'):
                raise SystemExit(f'Unexpected changes in {name}; no files written.')
    for name, content in updates.items():
        target = ROOT / name
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open('w', encoding='utf-8', newline='\n') as f:
            f.write(content)
        print(name)
    print('V3.1.5 applied. Review git diff and run tests before committing.')

if __name__ == '__main__':
    main()
